     utility={'calendar':'SOURCE_CLOCKS','check_schema':'STRUCTURE','checked':'LINEAGE_CUTOFF','ident':'IDENTITY','num':'PMF_SUPPORT','offer_view':'ORIGINAL_OFFER','pairs':'STRUCTURE','receipt':'SOURCE_REVISION','seal':'IMMUTABILITY','seed_for':'MC_INTEGRITY','sha':'IMMUTABILITY','strict_keys':'STRUCTURE','validate_game_state':'EXACT_G_O_J'}
